option.value:
name: Deploy - School Runner
on: # Manual deploy button in GitHub Actions UI workflow_dispatch: # Auto deploy only after CI workflow succeeds on main workflow_run: workflows: ["CI - Spring Boot Test"] types: [completed] branches: [main]
jobs: deploy: name: Deploy on self-hosted runner if: github.event_name == 'workflow_dispatch' || github.event.workflow_run.conclusion == 'success' runs-on: [self-hosted, windows] env: IMAGE_NAME: synctrip-backend CONTAINER_NAME: synctrip-backend IMAGE_TAG: ${{ github.sha }}
steps: - name: Checkout source uses: actions/checkout@v4
- name: Check Docker is available shell: powershell run: | docker --version docker info
- name: Build Docker image shell: powershell run: | docker build -t "$env:IMAGE_NAME:$env:IMAGE_TAG" -t "$env:IMAGE_NAME:latest" ./synctrip
- name: Stop old container if exists shell: powershell run: | $existing = docker ps -a --format "{{.Names}}" if ($existing -match "^$env:CONTAINER_NAME$") { docker stop $env:CONTAINER_NAME docker rm $env:CONTAINER_NAME }
- name: Run new container shell: powershell run: | docker run -d --name $env:CONTAINER_NAME --restart unless-stopped -p 8080:8080 "$env:IMAGE_NAME:latest"
- name: Verify container and port shell: powershell run: | Start-Sleep -Seconds 8 $running = docker ps --filter "name=$env:CONTAINER_NAME" --filter "status=running" --format "{{.Names}}" if (-not ($running -match "^$env:CONTAINER_NAME$")) { throw "Container is not running after deploy." }
$portCheck = Test-NetConnection -ComputerName 127.0.0.1 -Port 8080 if (-not $portCheck.TcpTestSucceeded) { throw "Container is running, but port 8080 is not accepting connections." }
Write-Host "Deploy check passed: container is running and port 8080 is open."

name: Deploy - School Runner
on: # Manual deploy button in GitHub Actions UI workflow_dispatch: # Auto deploy only after CI workflow succeeds on main workflow_run: workflows: ["CI - Spring Boot Test"] types: [completed] branches: [main]
jobs: deploy: name: Deploy on self-hosted runner if: > (github.event_name == 'workflow_dispatch' && github.ref == 'refs/heads/main') || (github.event_name == 'workflow_run' && github.event.workflow_run.conclusion == 'success' && github.event.workflow_run.head_branch == 'main') runs-on: [self-hosted, windows] concurrency: group: production-deploy cancel-in-progress: true env: IMAGE_NAME: synctrip-backend CONTAINER_NAME: synctrip-backend IMAGE_TAG: ${{ github.event_name == 'workflow_run' && github.event.workflow_run.head_sha || github.sha }}
steps: - name: Checkout source uses: actions/checkout@v4 with: ref: ${{ github.event_name == 'workflow_run' && github.event.workflow_run.head_sha || github.sha }}
- name: Check Docker is available shell: powershell run: | docker --version docker info
- name: Build Docker image shell: powershell run: | docker build -t "$env:IMAGE_NAME:$env:IMAGE_TAG" -t "$env:IMAGE_NAME:latest" ./synctrip
- name: Stop old container if exists shell: powershell run: | $existing = docker ps -a --format "{{.Names}}" if ($existing -match "^$env:CONTAINER_NAME$") { docker stop $env:CONTAINER_NAME docker rm $env:CONTAINER_NAME }
- name: Run new container shell: powershell run: | docker run -d --name $env:CONTAINER_NAME --restart unless-stopped -p 8080:8080 "$env:IMAGE_NAME:latest"
- name: Verify container and port shell: powershell run: | Start-Sleep -Seconds 8 $running = docker ps --filter "name=$env:CONTAINER_NAME" --filter "status=running" --format "{{.Names}}" if (-not ($running -match "^$env:CONTAINER_NAME$")) { throw "Container is not running after deploy." }
$portCheck = Test-NetConnection -ComputerName 127.0.0.1 -Port 8080 if (-not $portCheck.TcpTestSucceeded) { throw "Container is running, but port 8080 is not accepting connections." }
Write-Host "Deploy check passed: container is running and port 8080 is open."
